input.command:
$repos = @("$HOME\.claude", "$HOME\.claude\skills", "$HOME\.claude\global-memory")
foreach ($r in $repos) {
  Write-Output "=== $r"
  if (-not (Test-Path "$r\.git")) { Write-Output "NOT A REPO"; continue }
  git -C $r status --porcelain | Measure-Object | ForEach-Object { "uncommitted: $($_.Count)" }
  git -C $r rev-parse --abbrev-ref HEAD
  git -C $r log -1 --format="%h %ci %s"
}
Test-Path "$HOME\.claude\machine.md"

